function schedule(){clearInterval(timer);clearInterval(routeTimer);clearInterval(deliveryTimer);timer=null;routeTimer=null;deliveryTimer=null;section.classList.toggle('br-paused',paused||!document.body.classList.contains('v-brochure')||document.hidden||reduced.matches);const svg=section.querySelector('.br-swarm-svg'),stop=paused||!routeVisible||document.hidden||reduced.matches||!document.body.classList.contains('v-brochure');section.querySelector('.br-swarm').classList.toggle('br-swarm-paused',stop);if(stop)svg.pauseAnimations?.();else svg.unpauseAnimations?.();if(deliveryVisible&&!paused&&!document.hidden&&!reduced.matches)deliveryTimer=setInterval(()=>renderDelivery((deliveryStep+1)%implementation.length),8500);if(routeVisible&&!paused&&!document.hidden&&!reduced.matches)routeTimer=setInterval(()=>{if(routeStep===4)mission=(mission+1)%swarmMissions.length;renderRouting((routeStep+1)%5);},5600);}
