section.addEventListener('click',e=>{const b=e.target.closest('[data-br-stage]');if(b)renderStep(+b.dataset.brStage);const m=e.target.closest('[data-br-mission]');if(m){mission=+m.dataset.brMission;renderRouting(0);schedule();}const delivery=e.target.closest('[data-br-delivery]');if(delivery){renderDelivery(+delivery.dataset.brDelivery);schedule();}if(e.target.closest('[data-br-delivery-next]')){renderDelivery((deliveryStep+1)%implementation.length);schedule();}if(e.target.closest('[data-br-route-next]')){renderRouting(Math.min(4,routeStep+1));schedule();}if(e.target.closest('[data-br-route-prev]')){renderRouting(Math.max(0,routeStep-1));schedule();}if(e.target.closest('[data-br-route-replay]')){renderRouting(0);schedule();}if(e.target.closest('[data-br-share]'))window.openBrochureShare?.();if(e.target.closest('[data-br-activity]'))window.openBrochureShare?.('history');if(e.target.closest('[data-br-pricing]')&&!publicView)goView('pricing');});
